import{_ as r,l as i,o as e,c as l,v as t,p as d,x as o,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"别名分析","description":"","frontmatter":{"title":"别名分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/alias-analysis.md","filePath":"cs/alias-analysis.md","lastUpdated":1789023840000}'),h={name:"cs/alias-analysis.md"};function u(_,a,m,A,f,T){const s=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="别名分析" tabindex="-1">别名分析 <a class="header-anchor" href="#别名分析" aria-label="Permalink to &quot;别名分析&quot;">​</a></h1><div class="epigraph"><p>两次访存是否可能指向同一对象，决定 load 能否外提、store 能否换序。分析必须可靠：把「可能别名」说成「不别名」会改语义。</p><footer>—— 据龙书 12.4 指针别名；Muchnick；ISO C `restrict`；Wilson and Lam 对照整理</footer></div><p>上一课<a href="/cs/polyhedral-model">多面体</a>在仿射下标下精确知道数组单元。缺口是<strong>指针</strong>：C 的 <code>*p</code> 与 <code>*q</code>。别名分析给出 Must / May / No。主干优化默认保守 May。本课钉分类与语言规则（类型别名、<code>restrict</code>），具体 points-to 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LICM、向量化、DCE 对 store 都问：中间有没有对同一地址的写。无分析则任何 store 杀死所有 load 的可用。缺口是<strong>别名查询接口</strong>，不是调度。</p><p>C：不同基本类型默认不别名（strict aliasing），<code>char*</code> 例外。打破规则是 UB，优化可当不别名——<a href="/cs/undefined-behavior-opt">UB 课</a>。<code>restrict</code> 是程序员承诺。</p><h3 id="may-不是「运行时有时别名」" tabindex="-1">May 不是「运行时有时别名」 <a class="header-anchor" href="#may-不是「运行时有时别名」" aria-label="Permalink to &quot;May 不是「运行时有时别名」&quot;">​</a></h3><p>May 是静态不知道。Must 是必同。查询 API：<code>alias(p,q) ∈ {No, May, Must}</code>。优化只用 No 当许可。</p><p><span class="marginnote">龙书指针分析导引。ISO C 别名规则。Fortran 默认不别名数组参数。本课不写 Steensgaard 算法，下一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>基线：按类型、按分配点（栈槽互异、malloc 不重叠除非语言允许）、按 <code>restrict</code>。字段敏感：结构体不同字段可不别名。再接到 points-to 图。</p>',11)),(e(),d(p,null,{default:o(()=>[c(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E6%AC%A1%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20TY%5B%22%E7%B1%BB%E5%9E%8B%20%2F%20restrict%22%5D%0A%20%20Q%20--%3E%20PT%5B%22%E6%8C%87%E5%90%91%E9%9B%86%22%5D%0A%20%20TY%20--%3E%20A%5B%22No%20%2F%20May%20%2F%20Must%22%5D%0A%20%20PT%20--%3E%20A%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与所有权：借用检查在源级已禁某些别名；降到 IR 后分析仍要跑，因 <code>unsafe</code> 与 FFI。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过程间：callee 是否写 <code>*p</code> 要摘要。无摘要则 May 写全局。不要把 Java 的类型精确当 C 的 <code>char*</code> 规则。</p><p>TBAA（type-based alias analysis）把语言规则编进 IR 元数据；错误的元数据 = 错误优化。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不实现 Andersen。后课默认：优化问别名，No 才激进。下一课 Andersen / Steensgaard 指向分析。</p><p>也不把别名当加密侧信道模型。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>别名查询：No 才允许把两次访存当独立。</li><li>语言规则（TBAA、restrict）是分析的输入。</li><li>可靠优先于精确。</li><li>出处：Aho et al. 龙书；ISO C；Muchnick。</li></ul>',9))])}const b=r(h,[["render",u]]);export{B as __pageData,b as default};
